--
-- Table structure for table `historyoftest`
--

DROP TABLE IF EXISTS `historyoftest`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `historyoftest` (
  `HistoryOfTestID` int NOT NULL AUTO_INCREMENT,
  `UserID` int NOT NULL,
