INSERT INTO `question` VALUES (188,1,1,'D','(A) Một người phụ nữ đang đứng cạnh chiếc bạn.\r\n(B) Một người phụ nữ đang đi lên những bậc thang\r\n(C) Một người phụ nữ đang bước vào toà nhà.\r\n(D) Một người phụ nữ đang nhìn vào tấm bản đồ.',1,'data/image3_7ebc9fed-c462-4019-a056-5866fe8ff565.webp',NULL),(189,1,1,'C','(A) Cô ấy đang bơi trên sông.\r\n(B) Cô ấy đang đi bộ cạnh đại dương\r\n(C) Những chiếc ghế được xếp bên bờ biển\r\n(D) Chiếc mũ đang nằm trên cát',2,'data/image34.webp',NULL),(190,1,1,'B','(A) Cô ấy đang với lấy một món đồ từ tủ trưng bày\r\n(B) Cô ấy đang giữ tay vào xe đẩy mua hàng\r\n(C) Một vài sản phẩm đang được sắp xếp trên các kệ\r\n(D) Một vài hàng hoá bị rơi trên sàn.',3,'data/image33.webp',NULL),(191,1,1,'C','(A) Chiếc hàng rào đang được sơn trong công viên.\r\n(B) Một trong những người phụ nữ đang mặc lên người chiếc áo khoác\r\n(C) Một vài người đang làm việc tại khu vườn\r\n(D) Một vài người đang nhìn lên cái cây.\r\n',4,'data/image1.webp',NULL),(192,1,1,'D','(A) Một chiếc thảm đang được cuộn lại\r\n\r\n(B) Một vài tấm rèm được đóng.\r\n\r\n(C) Một vài chiếc gối được xếp chồng lên sàn nhà.\r\n\r\n(D) Một vài tài liệu được đặt trước ghế sofa.\r\n\r\n',5,'data/image32.webp',NULL),(193,1,1,'A','(A) Một vài nhạc sĩ đang biểu diễn trên hiên nhà.\r\n(B) Một vài bậc thang được được sửa chữa.\r\n(C) Một vài giá treo nhạc đang được gập lại.\r\n(D) Một vài nhạc cụ đã được đựng trong hộp của chúng.',6,'data/image2.webp',NULL),(194,2,1,'B','7. Loại đồ ăn nào mà cửa hàng bán?\r\n(A) Thật là một công thức nấu ăn ngon\r\n(B) Họ có tất cả các loại pho mát\r\n(C) Cùng với áo khoác mới\r\n\r\n',7,NULL,NULL),(195,2,1,'A','8. Khi nào thì chúng ta nên rời đến sân bay?\r\n(A) Chiều nay lúc 2 giờ\r\n(B) Tôi thích ngồi ở lối đi hơn\r\n(C) Ông Choi đã đến đó vào năm ngoái.\r\n',8,NULL,NULL),(196,2,1,'B','9. Sự kiện tuyển dụng đang được tổ chức ở đâu?\r\n(A) Cô ấy gửi nó cho một đồng nghiệp\r\n(B) Trong phòng họp hội nghị chính\r\n(C) Nếu họ mở cửa đúng giờ\r\n\r\n',9,NULL,NULL),(197,2,1,'C','10. Tại sao ngân sách lại đang được cập nhật?\r\n(A) Khi chúng ta thuê toà nhà.\r\n(B) Cùng với các thiết kế mới.\r\n(C) Bởi vì có những số liệu bán hàng mới.',10,NULL,NULL),(198,2,1,'A','11. Bạn có thể thay ca cho tôi vào ngày mai không?\r\n(A) Không được, tôi đang trong ngày nghỉ\r\n(B) Trước khi anh ấy cập nhật trang web\r\n(C) Nó ở trên lịch trình sự kiện của thứ Ba\r\n',11,NULL,NULL),(199,2,1,'B','12. Ai đã đặt những rau củ này?\r\n(A) Tất cả trong số chúng\r\n(B) Tôi nghĩ là Luis đã làm.\r\n(C) Nó rất xuất sắc, cảm ơn bạn.',12,NULL,NULL),(206,2,1,'A','13. Tôi nên gửi những thông báo bao lâu một lần?\r\n(A) Một lần 1 tháng\r\n(B) Sau 3 giờ\r\n(C) Khoảng 1 nửa trong số chúng.',13,NULL,NULL),(207,3,1,'A','32. Tại sao người phụ nữ lại gọi điện?\r\n(A) Để yêu cầu thay đổi vé\r\n(B) Để đặt chỗ ăn tối\r\n(C) Để đặt hàng\r\n(D) Để lên kế hoạch cho một kỳ nghỉ',32,NULL,20),(208,3,1,'D','33. Tại sao người đàn ông lại xin lỗi?\r\n(A) Một sự kiện đã bị hủy bỏ.\r\n(B) Dòng người xếp hàng rất dài.\r\n(C) Không có tùy chọn thanh toán.\r\n(D) Một chương trình máy tính không hoạt động.',33,NULL,20),(209,3,1,'C','34. Người đàn ông nhắc nhở người phụ nữ về điều gì?\r\n(A) Phiếu ăn\r\n(B) Một số quà lưu niệm miễn phí\r\n(C) Việc tăng giá\r\n(D) Chính sách hoàn tiền',34,NULL,20),(210,3,1,'C','35. Diễn giả sẽ tham dự sự kiện gì sau ngày hôm nay?\r\n(A) Một hội chợ việc làm\r\n(B) Một buổi chiếu phim\r\n(C) Một bữa trưa\r\n(D) Một hội nghị',35,NULL,21),(211,3,1,'A','36. Tại sao người đàn ông lại nói, \'\'cô ấy có một chiếc xe tải\'\'?\r\n(A) Để gợi ý về việc xin đi nhờ\r\n(B) Để bày tỏ sự ngạc nhiên trước lựa chọn phương tiện của đồng nghiệp\r\n(C) Để giải thích lý do tại sao một đồng nghiệp đến trễ\r\n(D) Để làm rõ rằng chuyện một đồng nghiệp đã giúp anh ấy di chuyển',36,NULL,21),(212,3,1,'B','37. Người phụ nữ rất có thể sẽ làm gì tiếp theo?\r\n(A) Lên lịch lại một sự kiện\r\n(B) Nói chuyện với một đồng nghiệp khác\r\n(C) Yêu cầu thời gian nghỉ\r\n(D) G