INSERT INTO `typeonequestion` VALUES (188,'data/ets-test-01-part-1-1_8e5d7d4e-62f6-47fb-b360-817708c119df.mp3','A. A woman is standing near a desk.\r\nB. A woman is climbing some stairs.\r\nC. A woman is entering a building.\r\nD. A woman is looking at a map.'),(189,'data/ets-test-01-part-1-2.mp3','(A) She’s swimming in the water.\r\n(B) She’s jogging near the ocean.\r\n(C) Chairs are set up on the beach.\r\n(D) A hat is lying on the sand.'),(190,'data/ets-test-01-part-1-3 (1).mp3','(A) She’s reaching for an item from a display case.\r\n(B) She’s holding on to a shopping cart.\r\n(C) Some goods are being arranged on shelves.\r\n(D) Some merchandise has fallen on the floor.'),(191,'data/ets-test-01-part-1-4.mp3','(A) A fence is being painted in a park.\r\n(B) One of the women is putting on a jacket.\r\n(C) Some people are working in a garden.\r\n(D) Some people are looking up at the trees.'),(192,'data/ets-test-01-part-1-5.mp3','(A) A carpet is being rolled up.\r\n\r\n(B) Some curtains have been closed.\r\n\r\n(C) Some cushions are piled on the floor.\r\n\r\n(D) Some reading materials have been placed in front of a sofa.'),(193,'data/ets-test-01-part-1-6.mp3','(A) Some musicians are performing on a porch.\r\n(B) Some steps are being repaired.\r\n(C) Some music stands are being folded up.\r\n(D) Some instruments have been placed in their cases.'),(194,'data/ets-test-01-part-2-7.mp3','What type of food does that store sell?\r\n(A) What a delicious recipe.\r\n(B) They have all kinds of cheese.\r\n(C) With a new jacket.'),(195,'data/ets-test-01-part-2-8.mp3','When should we leave for the airport?\r\n(A) This afternoon at two o’clock.\r\n(B) I prefer an aisle seat.\r\n(C) Mr. Choi traveled there last year.'),(196,'data/ets-test-01-part-2-9.mp3','Where’s the hiring event being held?\r\n(A) She sent it to a colleague.\r\n(B) In the main conference room.\r\n(C) If they open on time.'),(197,'data/ets-test-01-part-2-10.mp3','Why is the budget being updated?\r\n(A) When we rented the building.\r\n(B) With the new designs.\r\n(C) Because new sales figures came in.'),(198,'data/ets-test-01-part-2-11.mp3','Can you cover my shift at work tomorrow?\r\n\r\n(A) No, I\'m taking the day off.\r\n\r\n(B) Before he updated the Web site.\r\n\r\n(C) It’s on the agenda for Tuesday.'),(199,'data/ets-test-01-part-2-12.mp3','Who ordered these vegetables?\r\n(A) All of it.\r\n(B) I believe Luis did.\r\n(C) it was excellent, thanks.'),(206,'data/ets-test-01-part-2-13.mp3','How often should I mail the notices?\r\n(A) Once a month.\r\n(B) After three o’clock.\r\n(C) About half of them.'),(246,'data/ets-test-01-part-2-14.mp3','Which folder are the documents in?\r\n(A) We agreed on the deadline.\r\n(B) Sure, I’ll take a look.\r\n(C) Let me show you.'),(247,'data/ets-test-01-part-2-15.mp3','Did you end up going to a movie or to the concert last night?\r\n(A) I saw the new action film.\r\n(B) It just ended.\r\n(C) Just a couple of my friends.'),(248,'data/ets-test-01-part-2-16.mp3','We’ll take the company bus to the conference center.\r\n(A) I’m sure it’s not.\r\n(B) Maybe we did.\r\n(C) That’s a good plan.'),(249,'data/ets-test-01-part-2-17.mp3','What should we put in the introduction to the report?\r\n(A) After the summary.\r\n(B) The research highlights.\r\n(C) I met him yesterday.'),(250,'data/ets-test-01-part-2-18.mp3','We should have a new logo designed.\r\n(A) They’re about five miles from here.\r\n(B) I know a good graphic artist.\r\n(C) An order for some new calendars.'),(251,'data/ets-test-01-part-2-19.mp3','Did you select a site for the new headquarters?\r\n(A) Is that so?\r\n(B) No one can attend the training.\r\n(C) Yes, in the center of town.'),(252,'data/ets-test-01-part-2-20.mp3','Who’s going to cancel the meeting?\r\n(A) Martin is the most senior team member.\r\n(B) Josie’s chair is broken.\r\n(C) The client signed the contract.'),(253,'data/ets-test-01-part-2-21.mp3','How was your business trip?\r\n(A) They found some just in time.\r\n(B) I like that idea.\r\n(C) It was very productive.'),(269,'data/ets-test-01-part-2-22.mp3','Why did Chae-Won hire an assistant?\r\n(A) She will submit an estimate in September.\r\n(B) Anyway, they thought I was late.\r\n(C) Haven’t you noticed how busy she is?'),(270,'data/ets-test-01-part-2-23.mp3','Would you mind showing me the new office space?\r\n(A) I think that’s correct.\r\n(B) Sure—it won’t take long.\r\n(C) Everyone available participated.'),(271,'data/ets-test-01-part-2-24.mp3','We\'re trying to decide where to order from for lunch.\r\n(A) I loved those sandwiches from Gino’s last week.\r\n(B) My brother’s friend was there.\r\n(C) I remember that song very well.'),(272,'data/ets-test-01-part-2-25.mp3','When do you plan to finish the advertising campaign?\r\n(A) Next to Irina\'s office.\r\n(B) By Monday morning at the latest.\r\n(C) Because it didn’t make sense to me.'),(273,'data/ets-test-01-part-2-26.mp3','Where will the guest speaker be joining us from?\r\n(A) Nobody shared the details with me.\r\n(B) He wasn’t gone too long.\r\n(C) First thing in the morning, I believe.'),(274,'data/ets-test-01-part-2-27.mp3','Wouldn’t you prefer that Mi-Sun lead the training?\r\n(A) No, I filed it three months ago.\r\n(B) I just gave them to the director.\r\n(C) I don’t think she works here anymore.'),(275,'data/ets-test-01-part-2-28.mp3','We should get some feedback on this book cover design.\r\n(A) Ahmed has a visual arts degree.\r\n(B) They probably skipped a week.\r\n(C) It was really hard to hear.'),(276,'data/ets-test-01-part-2-29.mp3','Would you be able to delay the meeting?\r\n(A) How much storage does it have?\r\n(B) Most people seemed to enjoy it\r\n(C) Tatyana needs to leave for the airport in an hour.'),(277,'data/ets-test-01-part-2-30.mp3','Will you rent a car or take the train while you’re visiting?\r\n(A) They found some near the coast.\r\n(B) I don’t like driving in the city.\r\n(C) Mostly some old desks.'),(278,'data/ets-test-01-part-2-31.mp3','Seven thirty at night is rather late for a meeting, isn’t it?\r\n(A) If people agree on it, I will.\r\n(B) I promise I’ll keep it short.\r\n(C) I am not sure who he meant.'),(431,'data/z5530521217968_99625ca2b5785454a1e8850e01411975.jpg','1'),(436,'data/audio_Part1_cau1.mp3','A. A woman is standing near a desk.\r\nB. A woman is climbing some stairs.\r\nC. A woman is entering a building.\r\nD. A woman is looking at a map.\r\n'),(442,'data/audio_Part1_cau1_6ae8a6b9-8e9c-4179-a9e2-ee7b82a5dcde.mp3','A. A woman is standing near a desk.\r\nB. A woman is climbing some stairs.\r\nC. A woman is entering a building.\r\nD. A woman is looking at a map.\r\n');
