-- Table structure for table `typetwoquestion`
--

DROP TABLE IF EXISTS `typetwoquestion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `typetwoquestion` (
  `QuestionID` int NOT NULL,
  `ContentAnswerA` varchar(100) DEFAULT NULL,
  `ContentAnswerB` varchar(100) DEFAULT NULL,
  `ContentAnswerC` varchar(100) DEFAULT NULL,
  `ContentAnswerD` varchar(100) DEFAULT NULL,
  `QuestionContent` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`QuestionID`),
  CONSTRAINT `TTQ1` FOREIGN KEY (`QuestionID`) REFERENCES `question` (`QuestionID`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

