INSERT INTO `vocabulary` VALUES (175,104,'accountant ','một người chịu trách nhiệm về tiền trong một doanh nghiệp, kế toán =a person responsible for the money in a business','n','My [accountant] takes care of my taxes (=Dịch: Kế toán viên của tôi lo việc đóng thuế cho tôi)\r\nMany [accountants] made it to the board having previously served as senior executives (=Dịch: Nhiều kế toán viên đã lọt vào hội đồng quản trị trước đây từng giữ chức vụ điều hành cấp cao)','ə\'kaʊntənt','data/02_Accounting.jpg.webp'),(176,104,'airport ','sân bay =the place where you go to get on a plane','n','Security checks have become really strict at the [airport]. (=Dịch: Kiểm tra an ninh đã trở nên thực sự nghiêm ngặt tại sân bay.)\r\nI checked online and saw that the plane had already touched down at the [airport]. (=Dịch: Tôi kiểm tra trên mạng và thấy máy bay đã hạ cánh xuống sân bay.)','\'eəpɔːt','data/01_shutterstock_758602234-min-1038x778 (1).jpg'),(177,104,'applicant ','ứng viên =a person who submits papers in order to do something, e.g. job applicant','n','Many [applicants] simply don\'t meet hiring requirements. (=Dịch: Nhiều ứng viên đơn giản là không đáp ứng được yêu cầu tuyển dụng.)\r\nSuccessful [applicants] will be notified in writing. (=Dịch: Ứng viên thành công sẽ được thông báo bằng văn bản.)','\'æplɪkənt','data/z5375641095319_b0ce4bde9e7730c6331ce1b3076104d3.jpg'),(178,104,'attendant ','người phục vụ =someone who waits on or tends to the needs of another','n','There are around 20 parking [attendants] employed in Bolton who hand out 28,000 tickets a year. (=Dịch: Có khoảng 20 nhân viên trông xe ở Bolton phát 28.000 vé mỗi năm.)\r\nHe works at a hotel and was just recently promoted from bellhop to room service [attendant]. (=Dịch: Anh ấy làm việc tại một khách sạn và vừa được thăng chức từ nhân viên trực tầng lên nhân viên phục vụ phòng.)','ə\'tendənt','data/09_Before-You-Become-A-Flight-Attendant-1024x538 (1).webp'),(179,104,'bicycle','xe đạp =a vehicle with two wheels and pedals','n','You should never ride your [bicycle] without lights at night. (=Dịch: Bạn không bao giờ nên đi xe đạp mà không có đèn vào ban đêm.)\r\nThe police are now looking for the man who placed the [bicycle] in front of the hairdressing salon. (=Dịch: Hiện cảnh sát đang truy lùng người đàn ông đặt xe đạp trước tiệm làm tóc.)','\'baɪsɪkl','data/products_BirdBike3_2_83e0e074-f50e-4cd1-abef-e0f7caf51917 (1).jpg'),(180,104,'brochure ','tờ gấp quảng cáo =a small paper book that gives information about a product or service','n','Enclosed is a [brochure] that highlights the benefits that you can receive as a corporate donor. (=Dịch: Kèm theo là một tập tài liệu nêu bật những lợi ích mà bạn có thể nhận được với tư cách là nhà tài trợ của công ty.)\r\nThey produced a [brochure] on healthy eating that was to be distributed in supermarkets. (=Dịch: Họ sản xuất một tập tài liệu về ăn uống lành mạnh để phân phát trong các siêu thị.)','\'brəʊʃər','data/11_iconic-canada-printing-tri-fold-mockup2048x2048-157346198382155702592.webp'),(181,104,'cafeteria ','quán ăn tự phục vụ =a restaurant where you serve yourself and pay a cashier','n','Employees have four different salads to choose from for lunch in the company [cafeteria]. (=Dịch: Nhân viên có bốn món salad khác nhau để lựa chọn cho bữa trưa tại căng tin của công ty.)\r\nThere were several [cafeterias] and restaurants inside, frequented by visitors and hurried workers alike. (=Dịch: Bên trong có một số quán ăn tự phục vụ và nhà hàng, nơi du khách cũng như những người lao động vội vã thường xuyên lui tới.)','kæfə\'tɪərɪə','data/images_cafeteria-la-gi-6.jpg'),(182,104,'caller ','người đang gọi điện cho bạn =the person that is phoning you','n','On Wednesday nearly all the phone lines were continuously busy, with [callers] waiting approximately 30 minutes. (=Dịch: Vào thứ Tư, gần như tất cả các đường dây điện thoại đều bận, người gọi phải đợi khoảng 30 phút.)\r\nA special advice line was swamped by hundreds of [callers] (=Dịch: Đường dây tư vấn đặc biệt tràn ngập hàng trăm người gọi)','\'kɔːlər','data/02_callerid-768x512.webp'),(184,104,'candidate ','ứng viên =a person who submits papers in order to do something, e.g. job applicant','n','There are three [candidates] standing in the election. (=Dịch: Có ba ứng cử viên tham gia tranh cử.)\r\nThe English Department is a likely [candidate] for staff cuts. (=Dịch: Khoa Tiếng Anh có thể là đối tượng bị cắt giảm nhân sự)','\'kændɪdət','data/z5375641095319_b0ce4bde9e7730c6331ce1b3076104d3.jpg'),(230,140,'accountant','một người chịu trách nhiệm về tiền trong một doanh nghiệp, kế toán','n','Ví dụ:\r\nMy [accountant] takes care of my taxes (=Dịch: Kế toán của tôi lo liệu thuế của tôi)\r\nTrainee [accountants] average £12,000 per year. (=Dịch: Các thực tập sinh kế toán trung bình kiếm được 12,000 bảng Anh mỗi năm.)\r\nHis [accountant] had aided and abetted him in the fraud. (=Dịch: Kế toán của anh ấy đã giúp đỡ và đồng lõa với anh ấy trong vụ lừa đảo.)','əˈkaʊn.tənt','data/02_Accounting.jpg_6837f1bb-eb27-4c5e-834d-08f1c3c802ec.webp'),(233,145,'accept','nhận, chấp nhận','verb','We accept payment by Visa Electron, Visa, Switch, Maestro, Mastercard, JCB, Solo, check or cash. (Chúng tôi chấp nhận thanh toán bằng thẻ Visa Electron, Visa, Switch, Maestro, Mastercard, JCB, Solo, séc hoặc tiền mặt.)\r\n','əkˈsept','data/4_accept.webp'),(234,147,'yes','dùng để đồng ý hoặc xác nhận','adv','Yes, I agree with you. (=Dịch: Vâng, tôi đồng ý với bạn.)\r\nShe answered yes to the question. (=Dịch: Cô ấy trả lời có cho câu hỏi.)','jes','data/yes.jpg'),(235,147,'hello','lời chào hỏi ban đầu','noun','Hello, how are you?...','həˈləʊ','data/hello.jpg');
/*!40000 ALTER TABLE `vocabulary` ENABLE KEYS */;
UNLOCK TABLES;

